/* C API of the Rust port of `path/`, generated by rust-anything. */
#ifndef XYZTERM_PATH_H
#define XYZTERM_PATH_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

int compare_paths2(const char *path1, size_t length1, const char *path2, size_t length2);
int compare_paths(const char *path1, const char *path2);

/* The same functions under `rust_anything_` names, for shadow runs. */
int rust_anything_compare_paths2(const char *path1, size_t length1, const char *path2, size_t length2);
int rust_anything_compare_paths(const char *path1, const char *path2);

#endif /* XYZTERM_PATH_H */
